class Point {
public:
    static Point rectangular(float x, float y) { return Point{x, y}; }
    static Point polar(float r, float a) { return Point{r * std::cos(a), r * std::sin(a)}; }
private:
    Point(float x, float y) : x_(x), y_(y) {}     // no public constructor
    float x_, y_;
};
